message.content:
{
  "description": "The creature is a large, stout four-legged mammal standing in right-facing profile, covered in dense shaggy brown fur like a bear with a lighter tan muzzle. Its bear-like body is interspersed with glossy, dark reddish-brown hard structures resembling beetle wing-covers, with several smooth domed plates embedded in the fur of the neck, shoulder and side, and two large translucent membranous wings with dark brown veining protruding from the mid-body and lower chest. The flanks show rows of narrow dark slit openings in the fur, and the rear ends in a long segmented glossy tail tipped with a small forked claw.",
  "parts": [
    {
      "part": "head",
      "looks_like": "bear-like head with elongated snout, black nose, small brown eyes, light tan fur on the muzzle and darker brown fur on the crown and cheeks",
      "where": "at the front top of the body, facing right"
    },
    {
      "part": "ears",
      "looks_like": "two small rounded furry ears with dense brown fur",
      "where": "on top of the head, one slightly behind the other"
    },
    {
      "part": "legs",
      "looks_like": "four thick heavily furred legs with long brown hair, darker toward the lower leg",
      "where": "supporting the body, two front legs under the chest and two hind legs under the hips"
    },
    {
      "part": "feet",
      "looks_like": "four large broad paws with rounded toes and long pale curved claws on each toe",
      "where": "at the ends of the four legs on the ground"
    },
    {
      "part": "tail",
      "looks_like": "long segmented glossy dark reddish-brown tail made of overlapping hard plates, tapering toward the tip and ending in two small curved claws",
      "where": "extending from the rear of the body, hanging down behind the hind legs"
    },
    {
      "part": "wings",
      "looks_like": "two large translucent pale tan membranous wings with dark brown branching veins and a slightly shiny, veined texture, resembling insect wings",
      "where": "one large wing protruding laterally from the mid-side of the body and one smaller wing protruding from the lower chest on the opposite side"
    },
    {
      "part": "shell",
      "looks_like": "several smooth, domed, highly glossy dark reddish-brown hard shells with a central seam, resembling beetle elytra",
      "where": "embedded in the fur along the back of the neck, side of the neck, shoulder and mid-side, with one large shell below the large wing"
    },
    {
      "part": "plates",
      "looks_like": "overlapping hard glossy dark plates forming both the domed shells on the torso and the segmented rings of the tail",
      "where": "on the neck, shoulder, side and chest as domed covers, and as stacked segments along the entire tail"
    },
    {
      "part": "gills",
      "looks_like": "rows of narrow vertical slit-like openings with dark interiors in the fur, about five slits on the mid-flank and about nine slits in a curved row over the hip",
      "where": "on the side of the torso behind the large wing and on the upper hindquarter"
    },
    {
      "part": "markings",
      "looks_like": "no distinct color pattern beyond the contrast of brown fur and dark glossy plates, with the slit openings appearing as dark linear marks in the fur",
      "where": "along the mid-body flank and hip where the slits are located"
    }
  ],
  "attached_objects": [],
  "animals": [
    "bear",
    "beetle"
  ],
  "separate_bodies": 1,
  "heads": 1,
  "walking_legs": 4,
  "wings": 2,
  "extra_limb_pieces": 0,
  "tails": 1
}
